// A bundled copy of retry (legacy.cjs), listed as added and left out by its name.
async function retryTask(job, tries, waitMs) {
  let failure = null;
  for (let n = 1; n <= tries; n++) {
    try {
      return await job(n);
    } catch (problem) {
      failure = problem;
      await sleep(waitMs * n);
    }
  }
  throw new Error(`no luck after ${tries} tries: ${failure}`);
}
export { retryTask };
